import { Role } from '@prisma/client';
import prisma from '../db';
import { BadRequestError, ForbiddenError, NotFoundError } from '../utils/AppError';
import bcrypt from 'bcrypt';

export interface UpdateUserInput {
  name?: string;
  bio?: string | null;
  avatar?: string | null;
  role?: Role;
}

export interface ChangePasswordInput {
  currentPassword: string;
  newPassword: string;
}

// 获取所有用户（仅管理员）
export const getAllUsers = async () => {
  const users = await prisma.user.findMany({
    select: {
      id: true,
      email: true,
      name: true,
      bio: true,
      avatar: true,
      role: true,
      createdAt: true,
      updatedAt: true,
    },
    orderBy: {
      createdAt: 'desc',
    },
  });
  return users;
};

// 根据ID获取用户（仅管理员或用户本人）
export const getUserById = async (userId: number, requestingUserId?: number, requestingUserRole?: Role) => {
  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: {
      id: true,
      email: true,
      name: true,
      bio: true,
      avatar: true,
      role: true,
      createdAt: true,
      updatedAt: true,
    },
  });

  if (!user) {
    throw new NotFoundError('User not found');
  }

  // 允许管理员或用户本人访问
  if (requestingUserRole !== Role.ADMIN && requestingUserId !== userId) {
    throw new ForbiddenError('You are not allowed to access this user');
  }

  return user;
};

// 更新用户信息（仅管理员或用户本人）
export const updateUser = async (
  userId: number,
  input: UpdateUserInput,
  requestingUserId?: number,
  requestingUserRole?: Role
) => {
  // 验证权限：管理员可以更新任何用户，普通用户只能更新自己的信息
  if (requestingUserRole !== Role.ADMIN && requestingUserId !== userId) {
    throw new ForbiddenError('You are not allowed to update this user');
  }

  // 普通用户不能修改自己的角色
  if (input.role && requestingUserRole !== Role.ADMIN) {
    throw new ForbiddenError('Only administrators can change user roles');
  }

  // 检查邮箱是否已存在（如果需要更新邮箱，但这里邮箱不允许更新）
  // 邮箱作为唯一标识符，不允许通过此端点修改，如需修改邮箱应单独实现

  const updatedUser = await prisma.user.update({
    where: { id: userId },
    data: {
      name: input.name,
      bio: input.bio,
      avatar: input.avatar,
      role: input.role,
    },
    select: {
      id: true,
      email: true,
      name: true,
      bio: true,
      avatar: true,
      role: true,
      createdAt: true,
      updatedAt: true,
    },
  });

  return updatedUser;
};

// 修改密码（仅用户本人）
export const changePassword = async (
  userId: number,
  input: ChangePasswordInput,
  requestingUserId?: number,
  requestingUserRole?: Role
) => {
  // 只能修改自己的密码，除非是管理员
  if (requestingUserRole !== Role.ADMIN && requestingUserId !== userId) {
    throw new ForbiddenError('You are not allowed to change this user\'s password');
  }

  // 获取用户并验证当前密码
  const user = await prisma.user.findUnique({
    where: { id: userId },
  });

  if (!user) {
    throw new NotFoundError('User not found');
  }

  // 验证当前密码（如果是管理员修改他人密码，是否需要验证？这里我们要求管理员也提供当前密码）
  const isValidPassword = await bcrypt.compare(input.currentPassword, user.passwordHash);
  if (!isValidPassword) {
    throw new BadRequestError('Current password is incorrect');
  }

  // 哈希新密码
  const hashedNewPassword = await bcrypt.hash(input.newPassword, 10);

  // 更新密码
  await prisma.user.update({
    where: { id: userId },
    data: {
      passwordHash: hashedNewPassword,
    },
  });

  return { message: 'Password updated successfully' };
};

// 删除用户（仅管理员）
export const deleteUser = async (userId: number, requestingUserRole?: Role) => {
  if (requestingUserRole !== Role.ADMIN) {
    throw new ForbiddenError('Only administrators can delete users');
  }

  // 检查用户是否存在
  const user = await prisma.user.findUnique({
    where: { id: userId },
  });

  if (!user) {
    throw new NotFoundError('User not found');
  }

  // 删除用户（级联删除由Prisma Schema中的onDelete Cascade处理）
  await prisma.user.delete({
    where: { id: userId },
  });

  return { message: 'User deleted successfully' };
};

// 获取用户统计信息（可选，用于仪表板）
export const getUserStats = async (userId: number) => {
  const [blogCount, draftCount, commentCount, likeCount, bookmarkCount] = await Promise.all([
    prisma.blog.count({ where: { authorId: userId, published: true } }),
    prisma.blog.count({ where: { authorId: userId, published: false } }),
    prisma.comment.count({ where: { authorId: userId } }),
    prisma.like.count({ where: { userId } }),
    prisma.bookmark.count({ where: { userId } }),
  ]);

  return {
    publishedBlogs: blogCount,
    drafts: draftCount,
    comments: commentCount,
    likes: likeCount,
    bookmarks: bookmarkCount,
  };
};

